  messagesList.innerHTML = messages.map(message => `
    <li class="message">
      <div class="message-header">
        <span>${new Date(message.created_at).toLocaleString()}</span>
      </div>
      <div class="message-text">${escapeHtml(message.text)}</div>
    </li>
  `).join('');
}

