      console.error('Error sending initial data:', error);
      res.write(`data: ${JSON.stringify({ error: 'Failed to load messages' })}\n\n`);
    });

  // Handle client disconnect
  req.on('close', () => {
    console.log('Client disconnected from SSE');
  });
});

